// ── Helper functions ─────────────────────────────────

export function getBestiaryEntry(id: string): BestiaryEntry | undefined {
  return BESTIARY.find(e => e.id === id);
}

export function getSpell(id: string): SpellEntry | undefined {
  return SPELLS_EXPANDED.find(s => s.id === id);
}

export function getMagicItem(id: string): MagicItem | undefined {
  return MAGIC_ITEMS.find(i => i.id === id);
}

export function getNPCTemplate(id: string): NPCTemplate | undefined {
  return NPC_TEMPLATES.find(n => n.id === id);
}

export function getLocation(id: string): LocationTemplate | undefined {
  return LOCATIONS.find(l => l.id === id);
}

export function getMonstersByCr(maxCr: number): BestiaryEntry[] {
  return BESTIARY.filter(m => m.cr <= maxCr);
}

export function getRandomElement<T>(arr: T[]): T {
  return arr[Math.floor(Math.random() * arr.length)];
}

export function getRandomEntries<T>(arr: T[], count: number): T[] {
  const shuffled = [...arr].sort(() => Math.random() - 0.5);
  return shuffled.slice(0, Math.min(count, arr.length));
}